import jep.Jep;

public class TestThreadClose {
    static Jep jepInstance = null;

    public static void main(String[] args) throws Exception {
        System.out.println("Testing Jep.close() from different thread...");

        // Create a thread that creates a Jep instance
        Thread t = new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    jepInstance = new Jep();
                    jepInstance.eval("print('Hello from Jep')");
                    System.out.println("Jep instance created successfully in thread: " + Thread.currentThread().getName());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        });

        t.start();
        t.join();

        System.out.println("Creating thread has finished.");
        System.out.println("Jep instance closed: " + jepInstance.isClosed());

        // Now try to close from main thread
        // This should NOT crash - it should handle it gracefully
        System.out.println("Attempting to close Jep instance from different thread...");
        try {
            jepInstance.close();
            System.out.println("close() returned without crashing");
        } catch (IllegalStateException e) {
            // This shouldn't happen since the thread is dead
            System.out.println("IllegalStateException caught: " + e.getMessage());
        }

        System.out.println("JVM did not crash!");
        System.out.println("Test passed.");
    }
}
