{"command": "cat > /tmp/TestNoCrash.java << 'EOF'
import jep.Jep;
import java.util.concurrent.ConcurrentHashMap;

/**
 * This test simulates the scenario from the PR description:
 * - A cache of jep instances which are bound to the container thread that created them.
 * - If the originating thread is disposed and at a later time we try to close the corresponding jep instance,
 *   we should NOT experience a JVM crash.
 */
public class TestNoCrash {
    static ConcurrentHashMap<String, Jep> jepCache = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        System.out.println("Simulating web container scenario from PR description...");

        // Simulate a "request thread" creating a Jep instance
        Thread requestThread = new Thread(() -> {
            try {
                Jep jep = new Jep();
                jep.eval("x = 1 + 2");
                jepCache.put("request1", jep);
                System.out.println("Jep instance created and stored in cache");
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, "RequestThread");

        requestThread.start();
        requestThread.join();

        System.out.println("Request thread has terminated.");
        System.out.println("Now trying to close the Jep instance from a different thread (e.g., cleanup thread)...");

        // Now simulate a cleanup thread trying to close the Jep
        Jep jep = jepCache.get("request1");
        if (jep != null) {
            System.out.println("Calling close() on Jep instance...");
            jep.close();
            System.out.println("close() returned without crashing the JVM!");
        }

        System.out.println("TEST PASSED: No JVM crash occurred.");
        System.out.println("The fix prevents the SIGSEGV that was described in the PR.");
    }
}
